INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 23, 'theory', 'Квиз: автоматизация oVirt');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 0, 'Как в REST API oVirt выражается действие, например запуск виртуальной машины?', '["GET на /vms/123?start=true", "PUT на коллекцию /vms с именем машины", "POST на /vms/123/start", "DELETE на /vms/123/start"]', 2, 'Действия оформлены как POST на ресурс с именем действия на конце; параметры, например async, передаются в теле. GET не должен менять состояние.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 1, 'Чем bearer-токен из SSO лучше базовой авторизации в скриптах?', '["Пароль отправляется один раз, токен живёт ограниченное время, а после ответа 401 запрашивают новый", "Токен никогда не истекает, поэтому повторы не нужны", "Базовая авторизация совсем не поддерживается менеджером", "Токен можно бесконечно обновлять без пароля"]', 0, 'Пароль уходит только при получении токена. Токен ограничен по времени, обновления у него нет: при 401 запрашивают новый.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 2, 'Что означает state: present в модуле ovirt_vm?', '["Создать машину и обязательно запустить её", "Остановить машину, если она работает", "Удалить машину", "Создать или обновить машину, не меняя её питание"]', 3, 'present создаёт или обновляет машину и оставляет питание как есть. Запуск делает running, остановку — stopped, удаление — absent.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 3, 'Зачем Linux-шаблон запечатывают перед клонированием?', '["Чтобы диск работал быстрее", "Чтобы убрать данные конкретной машины, такие как ключи хоста и идентификатор, и клоны не стали двойниками", "Чтобы запретить удаление шаблона", "Чтобы сжать образ диска"]', 1, 'Запечатывание стирает данные конкретной машины, например ключи хоста, идентификатор и журналы, а имя, сеть и ключи доступа затем выдаёт cloud-init при первой загрузке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 4, 'Какая стратегия повторов безопасна для автоматизации?', '["Повторять любой неудавшийся POST сразу, в плотном цикле", "Повторять под учётной записью администратора, чтобы обойти права", "Повторять чтение и операции желаемого состояния с растущей паузой и случайным разбросом", "Никогда не ждать между попытками"]', 2, 'Чтение и идемпотентные операции можно повторять; растущая пауза с разбросом не перегружает менеджер. Слепой повтор создания может дать дубликат.');
